const clamp=x=>Math.max(0,Math.min(1,x));
const mix=(a,b,q)=>({x:a.x+(b.x-a.x)*q,y:a.y+(b.y-a.y)*q});
// Fixed material-space fractures: no random shimmer or sliding when the frame turns.
export function fractureLayout(f={}){const impact={x:f.depotImpactX??-8,y:f.depotImpactY??-19},angles=[-3.05,-2.62,-2.16,-1.76,-1.25,-.77,-.14,.36,.92,1.48,2.05,2.63];return angles.map((angle,i)=>{const dx=Math.cos(angle),dy=Math.sin(angle),r=Math.min(Math.abs(dx)<1e-8?Infinity:(dx>0?480-impact.x:-480-impact.x)/dx,Math.abs(dy)<1e-8?Infinity:(dy>0?270-impact.y:-270-impact.y)/dy),end={x:impact.x+dx*r,y:impact.y+dy*r};const kink=(q,amount)=>{const p=mix(impact,end,q);return {x:p.x-dy*amount,y:p.y+dx*amount}};return {points:[impact,kink(.22+.035*(i%3),Math.sin(i*3.1)*11),kink(.58+.04*(i%2),Math.cos(i*2.7)*19),end],delay:(i*7%11)*.018,width:.7+(i%4)*.24,branch:i%3!==1}})}
export function traceFracture(c,points,progress){let lengths=points.slice(1).map((p,i)=>Math.hypot(p.x-points[i].x,p.y-points[i].y)),remaining=lengths.reduce((a,b)=>a+b,0)*clamp(progress);c.beginPath();c.moveTo(points[0].x,points[0].y);for(let i=0;i<lengths.length&&remaining>0;i++){const p=mix(points[i],points[i+1],Math.min(1,remaining/lengths[i]));c.lineTo(p.x,p.y);remaining-=lengths[i]}}
